CREATE TABLE IF NOT EXISTS "shipments" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,
  "number" bigint GENERATED BY DEFAULT AS IDENTITY,
  "sales_order_id" uuid NOT NULL REFERENCES "sales_orders"("id"),
  "status" varchar(20) NOT NULL DEFAULT 'preparada',
  "origin" text NOT NULL,
  "destination" text NOT NULL,
  "carrier" text,
  "planned_at" timestamptz,
  "dispatched_at" timestamptz,
  "delivered_at" timestamptz,
  "dispatch_key" uuid,
  "manifest_hash" varchar(64),
  "manifest_by" uuid REFERENCES "users"("id"),
  "created_by" uuid NOT NULL REFERENCES "users"("id"),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "shipments_status_ck" CHECK ("status" IN ('preparada','despachada','entregue')),
  CONSTRAINT "shipments_destination_ck" CHECK (length(trim("destination")) > 0),
  CONSTRAINT "shipments_tenant_id_uq" UNIQUE ("id", "tenant_id"),
  CONSTRAINT "shipments_tenant_order_uq" UNIQUE ("tenant_id", "sales_order_id"),
  CONSTRAINT "shipments_tenant_number_uq" UNIQUE ("tenant_id", "number"),
  CONSTRAINT "shipments_tenant_dispatch_key_uq" UNIQUE ("tenant_id", "dispatch_key")
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "shipments_tenant_order_idx" ON "shipments"("tenant_id", "sales_order_id");
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "shipment_items" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "shipment_id" uuid NOT NULL,
  "sales_order_item_id" uuid NOT NULL REFERENCES "quote_items"("id"),
  "production_order_item_id" uuid NOT NULL REFERENCES "production_order_items"("id"),
  "quantity" integer NOT NULL,
  "weight_kg" numeric(12,4) NOT NULL,
  "unit" varchar(20) NOT NULL DEFAULT 'un',
  CONSTRAINT "shipment_items_quantity_ck" CHECK ("quantity" > 0 AND "weight_kg" > 0),
  CONSTRAINT "shipment_items_shipment_fk" FOREIGN KEY ("shipment_id", "tenant_id") REFERENCES "shipments"("id", "tenant_id"),
  CONSTRAINT "shipment_items_shipment_item_uq" UNIQUE ("shipment_id", "sales_order_item_id")
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "shipment_items_tenant_item_idx" ON "shipment_items"("tenant_id", "sales_order_item_id");
