CREATE TABLE IF NOT EXISTS "shipment_events" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL,
  "shipment_id" uuid NOT NULL,
  "type" varchar(40) NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "source" varchar(20) NOT NULL DEFAULT 'manual',
  "location" text,
  "evidence_ref" text,
  "eta" timestamptz,
  "created_by" uuid NOT NULL REFERENCES "users"("id"),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "shipment_events_shipment_fk" FOREIGN KEY ("shipment_id", "tenant_id") REFERENCES "shipments"("id", "tenant_id"),
  CONSTRAINT "shipment_events_source_ck" CHECK ("source" IN ('manual','integrada'))
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "shipment_events_tenant_shipment_idx" ON "shipment_events"("tenant_id", "shipment_id", "created_at");
