CREATE TABLE IF NOT EXISTS "import_tracking" (
  "id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "tenant_id" uuid NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,
  "purchase_order_id" uuid NOT NULL REFERENCES "purchase_orders"("id"),
  "reference" text NOT NULL,
  "milestone" varchar(80) NOT NULL,
  "eta" timestamptz,
  "source" varchar(20) NOT NULL DEFAULT 'manual',
  "observed_at" timestamptz NOT NULL,
  "created_by" uuid NOT NULL REFERENCES "users"("id"),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "import_tracking_source_ck" CHECK ("source" IN ('manual','integrada')),
  CONSTRAINT "import_tracking_reference_ck" CHECK (length(trim("reference")) > 0)
);
